// The All settings panel: every setting in force, in the Agent pane's place,
// opened from the setup card's "All settings" link (the "JusPrin v2" canvas,
// page "Current Setup Card", the four "All settings" boards). The host reads
// the table (settings_catalog); this page only arranges it. Showing follows
// the selection in the 3D view: the whole project, one plate when the project
// has more than one, or one object, for which only what it sets itself is
// listed. The first version is read-only: the design's "Use project value"
// and "Remove" actions are not offered yet.

import { useEffect, useState } from 'react';
import { CatalogFilamentInfo, CatalogObjectInfo, CatalogOverrideInfo, CatalogPlateInfo, CatalogSettingInfo,
  SettingsCatalogPayload, WorkspaceContext } from '../bridge/protocol';
import { ActionMenu, AgentPaneToggle, MenuItem } from './ChatNavigation';

export type SettingsScope = { kind: 'project' } | { kind: 'plate'; id: string } | { kind: 'object'; id: string };
export type SettingsFilter = 'all' | 'changed';

// OrcaSlicer's process tab pages, in its order. A setting the tab does not
// index (empty page) is filed under Others.
export const PROCESS_PAGES = ['Quality', 'Strength', 'Speed', 'Support', 'Multimaterial', 'Others'];
// Side by side up to here; beyond it one slot at a time, from a picker.
export const COLUMN_SLOTS = 3;

export interface AllSettingsProps {
  context: WorkspaceContext;
  // Null while the host is reading it. A saved chat has no live table: pass
  // catalogFromContext(summary) and `saved`.
  catalog: SettingsCatalogPayload | null;
  saved?: boolean;
  // The host cannot read the table (an older build, or a non-FFF printer
  // reports it itself through `available`).
  unsupported?: boolean;
}

function plural(count: number, one: string, many: string): string {
  return `${count} ${count === 1 ? one : many}`;
}

function shortPreset(name: string): string {
  const separator = name.indexOf(' @');
  return separator < 0 ? name : name.slice(0, separator);
}

const sentence = (text: string) => {
  const words = text.replace(/[_-]+/g, ' ').trim();
  return words.charAt(0).toUpperCase() + words.slice(1);
};

// The volume an override is on ("bracket.stl / Mounting tabs" names the
// modifier), or nothing for the object itself.
function volumeName(local: CatalogOverrideInfo): string | undefined {
  const separator = local.target.indexOf(' / ');
  return separator < 0 ? undefined : local.target.slice(separator + 3);
}

// Which object the 3D view has: exactly one, or none to follow.
export function selectedObject(context: WorkspaceContext): string | null {
  const selection = context.selection;
  return selection.status === 'objects' && selection.objectIds.length === 1 ? selection.objectIds[0] : null;
}

// A saved chat's table, from the summary the chat saved: the settings that
// differed from the presets then, and the objects' own settings. The rest of
// the table was not saved, so the panel shows these as the changed ones.
export function catalogFromContext(context: WorkspaceContext): SettingsCatalogPayload {
  // "0.2 → 0.28 mm" says the unit once; each side gets it back.
  const split = (display: string): [string, string] => {
    const arrow = display.indexOf(' → ');
    if (arrow < 0) return [display, display];
    const before = display.slice(0, arrow);
    const after = display.slice(arrow + 3);
    const unit = after.match(/^-?[\d.,]+ (\D\S*)$/);
    return [unit && /^-?[\d.,]+$/.test(before) ? `${before} ${unit[1]}` : before, after];
  };
  const rows = (type: string): CatalogSettingInfo[] => context.presetDeltas
    .filter((delta) => (delta.presetType ?? 'process') === type)
    .map((delta) => {
      const [presetDisplay, display] = delta.display ? split(delta.display) : [delta.preset, delta.value];
      return { key: delta.key, label: delta.label || delta.key, page: delta.page ?? '', group: delta.group ?? '',
        value: delta.value, display, preset: delta.preset, presetDisplay };
    });
  const identity = context.setupIdentity;
  const plate = context.plates.find((item) => item.active);
  const applied = context.appliedSetup;
  return {
    available: true,
    process: { name: context.printer.process, settings: rows('process') },
    printer: { name: identity?.printer ?? context.printer.preset, settings: rows('printer') },
    filaments: (identity?.filaments ?? []).map((filament, index) => ({ slot: index + 1, preset: filament.preset,
      material: filament.material, colour: '', settings: index === 0 ? rows('filament') : [] })),
    plates: plate ? [{ id: plate.id, name: plate.name, active: true, bedType: identity?.plateType ?? '', ownBedType: false,
      bedTempKey: '', bedTempInitialKey: '', own: [] }] : [],
    objects: (applied?.objects ?? []).map((name, index) => ({
      id: plate?.objects.find((item) => item.name === name)?.id ?? `saved-${index}`, name, plateId: plate?.id,
      overrides: (applied?.localOverrides ?? []).filter((local) => local.object === index)
        .map(({ target, kind, key, value, label, display }) => ({ target, kind, key, value, label, display })) })),
  };
}

const lower = (text: string) => text.toLowerCase();

function matches(setting: { label: string; key: string }, query: string): boolean {
  const wanted = lower(query.trim());
  return !wanted || lower(setting.label).includes(wanted) || lower(setting.key).includes(wanted);
}

const changed = (setting: CatalogSettingInfo) => setting.preset !== undefined;

// Consecutive runs that share a heading, in the order they first appear.
function runs<T>(items: T[], heading: (item: T) => string): [string, T[]][] {
  const groups = new Map<string, T[]>();
  for (const item of items) groups.set(heading(item), [...(groups.get(heading(item)) ?? []), item]);
  return [...groups];
}

const pageOf = (setting: CatalogSettingInfo) => PROCESS_PAGES.includes(setting.page) ? setting.page : 'Others';

// -- Rows ---------------------------------------------------------------------

function Row({ label, value, bold, muted, notes, tag }: {
  label: string; value: string; bold?: boolean; muted?: boolean; notes?: string[]; tag?: string;
}) {
  return <div className={bold ? 'all-settings-row all-settings-row--changed' : 'all-settings-row'}>
    <div className="all-settings-row-line">
      <span className="all-settings-row-name" title={label}>{label}</span>
      <span className={['all-settings-row-value', bold && 'all-settings-row-value--bold', muted && 'all-settings-row-value--muted']
        .filter(Boolean).join(' ')}>{value}</span>
      {tag && <span className="all-settings-row-tag">{tag}</span>}
    </div>
    {(notes ?? []).filter(Boolean).map((note) => <p className="all-settings-row-note" key={note}>{note}</p>)}
  </div>;
}

// A group's header: a disclosure when it has rows, a plain line that says
// "same as project" (or whatever `summary` says) when it has none.
function Group({ name, summary, open, onToggle, children, count }: {
  name: string; summary: string; open: boolean; onToggle: () => void; children?: React.ReactNode; count: number;
}) {
  if (count === 0)
    return <div className="all-settings-group"><div className="all-settings-group-header all-settings-group-header--empty">
      <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
      <span className="all-settings-group-name">{name}</span>
      <span className="all-settings-group-summary">{summary}</span>
    </div></div>;
  return <div className="all-settings-group">
    <button type="button" className="all-settings-group-header" aria-expanded={open} onClick={onToggle}>
      <span className={`jp-icon jp-icon-chevron-${open ? 'down' : 'right'}`} aria-hidden="true" />
      <span className="all-settings-group-name">{name}</span>
      <span className="all-settings-group-summary">{summary}</span>
    </button>
    {open && <div className="all-settings-group-rows">{children}</div>}
  </div>;
}

// Rows of one preset under their Orca groups, as a name and a value; a
// changed value is bold with the preset's under it.
function PresetRows({ settings, notes, byPage }: {
  settings: CatalogSettingInfo[]; notes?: (setting: CatalogSettingInfo) => string[]; byPage?: boolean;
}) {
  return <>{runs(settings, (setting) => byPage ? [setting.page, setting.group].filter(Boolean).join(' · ') : setting.group)
    .map(([heading, rows]) => <div className="all-settings-run" key={heading || '(ungrouped)'}>
      {heading && <p className="all-settings-run-name">{heading}</p>}
      {rows.map((setting) => <Row key={setting.key} label={setting.label} bold={changed(setting)}
        muted={setting.inherited} value={setting.inherited ? 'printer' : setting.display}
        notes={[changed(setting) ? `Preset: ${setting.presetDisplay ?? setting.preset}` : '',
          setting.inherited ? `From the printer: ${setting.inheritedDisplay}` : '', ...(notes?.(setting) ?? [])]} />)}
    </div>)}</>;
}

// -- The Filament group ---------------------------------------------------------

function Swatch({ colour, label }: { colour: string; label: string }) {
  return <span className="all-settings-swatch" role="img" aria-label={label} title={label}
    style={colour ? { background: colour } : undefined} />;
}

// The filament rows, with the bed temperature named for the plate type the
// shown plate prints with.
function filamentRows(filament: CatalogFilamentInfo, plate: CatalogPlateInfo | undefined, query: string,
  filter: SettingsFilter): CatalogSettingInfo[] {
  return filament.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)))
    .map((setting) => plate?.bedType && (setting.key === plate.bedTempKey || setting.key === plate.bedTempInitialKey)
      ? { ...setting, label: `${setting.label} · ${plate.bedType}` } : setting);
}

// Two or three slots side by side: one column per slot, the rows being slot
// 1's settings in order. A value inherited from the printer reads "printer";
// a filament's own override, or a change from its preset, is bold with a
// note under the row.
function FilamentColumns({ filaments, plate, query, filter }: {
  filaments: CatalogFilamentInfo[]; plate?: CatalogPlateInfo; query: string; filter: SettingsFilter;
}) {
  const perSlot = filaments.map((filament) => new Map(filament.settings.map((setting) => [setting.key, setting])));
  const lead = filamentRows(filaments[0], plate, query, 'all');
  // The changed filter keeps a row some slot changed from its preset, or
  // sets itself where another slot leaves it to the printer.
  const shown = filter === 'all' ? lead : lead.filter((row) => perSlot.some((slot) => {
    const cell = slot.get(row.key);
    return !!cell && (changed(cell) || overridesPrinter(cell, perSlot, row.key));
  }));
  return <div className="all-settings-columns" style={{ '--all-settings-slots': filaments.length } as React.CSSProperties}>
    <div className="all-settings-columns-head">
      <span />
      {filaments.map((filament) => <span className="all-settings-column-slot" key={filament.slot}>
        <Swatch colour={filament.colour} label={`Slot ${filament.slot} · ${shortPreset(filament.preset)}`} />
        <span className="all-settings-column-slot-name">Slot {filament.slot}</span>
        <span className="all-settings-column-slot-material">{filament.material || shortPreset(filament.preset)}</span>
      </span>)}
    </div>
    {runs(shown, (setting) => [setting.page, setting.group].filter(Boolean).join(' · ')).map(([heading, group]) =>
      <div className="all-settings-run" key={heading || '(ungrouped)'}>
        {heading && <p className="all-settings-run-name">{heading}</p>}
        {group.map((lead) => {
          const cells = perSlot.map((slot) => slot.get(lead.key));
          const notes = cells.flatMap((cell, index) => {
            if (!cell) return [];
            const slot = filaments[index].slot;
            const lines: string[] = [];
            if (changed(cell)) lines.push(`Slot ${slot} preset: ${cell.presetDisplay ?? cell.preset}`);
            if (overridesPrinter(cell, perSlot, lead.key))
              lines.push(`Slot ${slot} overrides the printer’s ${printerValue(perSlot, lead.key)}.`);
            return lines;
          });
          const anyBold = cells.some((cell) => cell && (changed(cell) || overridesPrinter(cell, perSlot, lead.key)));
          return <div className={anyBold ? 'all-settings-row all-settings-row--changed' : 'all-settings-row'} key={lead.key}>
            <div className="all-settings-row-line all-settings-row-line--columns">
              <span className="all-settings-row-name" title={lead.label}>{lead.label}</span>
              {cells.map((cell, index) => <span key={index} className={['all-settings-row-value',
                cell && (changed(cell) || overridesPrinter(cell, perSlot, lead.key)) && 'all-settings-row-value--bold',
                cell?.inherited && 'all-settings-row-value--muted'].filter(Boolean).join(' ')}>
                {cell ? cell.inherited ? 'printer' : cell.display : '—'}</span>)}
            </div>
            {notes.map((note) => <p className="all-settings-row-note" key={note}>{note}</p>)}
          </div>;
        })}
      </div>)}
  </div>;
}

// A filament's own value for a setting another slot leaves to the printer.
function overridesPrinter(cell: CatalogSettingInfo, perSlot: Map<string, CatalogSettingInfo>[], key: string): boolean {
  return !cell.inherited && perSlot.some((slot) => slot.get(key)?.inherited);
}

function printerValue(perSlot: Map<string, CatalogSettingInfo>[], key: string): string {
  for (const slot of perSlot) {
    const cell = slot.get(key);
    if (cell?.inherited) return cell.inheritedDisplay ?? '';
  }
  return '';
}

// -- The panel ------------------------------------------------------------------

export function AllSettingsHeader({ onBack, onCollapse }: { onBack: () => void; onCollapse: () => void }) {
  return <header className="chat-header all-settings-header">
    <button type="button" className="chat-icon" aria-label="Back to chat" title="Back to chat" autoFocus onClick={onBack}>
      <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" />
    </button>
    <h1>All settings</h1>
    <AgentPaneToggle onCollapse={onCollapse} />
  </header>;
}

function scopeKey(scope: SettingsScope): string {
  return scope.kind === 'project' ? 'project' : `${scope.kind}:${scope.id}`;
}

export function AllSettings({ context, catalog, saved = false, unsupported = false }: AllSettingsProps) {
  const selected = selectedObject(context);
  const follow = (id: string | null): SettingsScope | null => id ? { kind: 'object', id } : null;
  const [chosen, setChosen] = useState<SettingsScope | null>(() => follow(selected));
  // The 3D view's selection wins whenever it changes; a choice made here
  // holds until then.
  useEffect(() => { setChosen(follow(selected)); }, [selected]);
  const [query, setQuery] = useState('');
  const [filter, setFilter] = useState<SettingsFilter>(saved ? 'changed' : 'all');
  const [slot, setSlot] = useState(1);
  const [open, setOpen] = useState<Record<string, boolean>>({});

  const plates = catalog?.plates ?? context.plates.map((plate) => ({ id: plate.id, name: plate.name, active: plate.active,
    bedType: '', ownBedType: false, bedTempKey: '', bedTempInitialKey: '', own: [] as CatalogSettingInfo[] }));
  const objects: CatalogObjectInfo[] = catalog?.objects ?? context.plates.flatMap((plate) =>
    plate.objects.map((object) => ({ id: object.id, name: object.name, plateId: plate.id, overrides: [] })));
  const scope: SettingsScope = chosen && (chosen.kind === 'project' ||
    (chosen.kind === 'object' ? objects : plates).some((item) => item.id === chosen.id)) ? chosen : { kind: 'project' };
  const activePlate = plates.find((plate) => plate.active);

  const options: MenuItem[] = [
    { key: 'project', label: 'Whole project', current: scope.kind === 'project', onSelect: () => setChosen({ kind: 'project' }) },
    ...(plates.length > 1 ? plates.map((plate) => ({ key: `plate:${plate.id}`, label: plate.name,
      current: scope.kind === 'plate' && scope.id === plate.id, onSelect: () => setChosen({ kind: 'plate', id: plate.id }) })) : []),
    ...objects.map((object) => ({ key: `object:${object.id}`, label: object.name,
      current: scope.kind === 'object' && scope.id === object.id, onSelect: () => setChosen({ kind: 'object', id: object.id }) })),
  ];
  const shownName = options.find((option) => option.current)?.label ?? 'Whole project';

  const toggle = (name: string, fallback: boolean) => setOpen((before) => ({ ...before, [name]: !(before[name] ?? fallback) }));
  const isOpen = (name: string, fallback: boolean) => query.trim() ? true : open[name] ?? fallback;

  const identity = context.setupIdentity;
  const process = catalog?.process;
  const processChanges = process ? process.settings.filter(changed).length
    : context.presetDeltas.filter((delta) => (delta.presetType ?? 'process') === 'process').length;
  const objectsHere = objects.filter((object) => !activePlate || object.plateId === activePlate.id || !object.plateId);
  const withOwn = objectsHere.filter((object) => object.overrides.length > 0);

  // What the row of one process setting says about the objects that print
  // it differently: "Mounting tabs: 6".
  const overrideNotes = (setting: CatalogSettingInfo): string[] => objectsHere.flatMap((object) =>
    object.overrides.filter((local) => local.key === setting.key).map((local) =>
      `${volumeName(local) ?? object.name}: ${local.display || local.value}`));

  const body = () => {
    if (unsupported) return <p className="all-settings-note">This JusPrin build cannot list the settings.</p>;
    if (!catalog) return <p className="all-settings-note" role="status">Reading the settings…</p>;
    if (!catalog.available) return <p className="all-settings-note">No settings to show: the selected printer is not an FFF printer.</p>;
    if (scope.kind === 'object') return objectBody(objects.find((object) => object.id === scope.id)!);
    if (scope.kind === 'plate') return plateBody(plates.find((plate) => plate.id === scope.id)!);
    return projectBody();
  };

  const projectBody = () => {
    const processRows = catalog!.process.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)));
    const byPage = new Map(runs(processRows, pageOf));
    const printerRows = catalog!.printer.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)));
    const filaments = catalog!.filaments;
    const filamentShown = filaments.length > COLUMN_SLOTS ? filaments.filter((item) => item.slot === slot) : filaments;
    const filamentRowsShown = filamentShown.length === 1 ? filamentRows(filamentShown[0], activePlate, query, filter) : [];
    const filamentCount = filamentShown.length === 1 ? filamentRowsShown.length
      : filaments.length === 0 ? 0 : filamentRows(filaments[0], activePlate, query, 'all').length;
    const filamentChanges = filaments.reduce((total, item) => total + item.settings.filter(changed).length, 0);
    const printerChanges = catalog!.printer.settings.filter(changed).length;
    const summary = (count: number) => count > 0 ? `${count} changed` : 'from the preset';
    return <>
      <div className="all-settings-presets" data-testid="all-settings-presets">
        <div className="all-settings-preset"><span className="all-settings-preset-label">Printer</span>
          <span className="all-settings-preset-value">{[identity?.printer || catalog!.printer.name,
            identity?.nozzles.length ? `${identity.nozzles.join(' / ')} mm nozzle` : ''].filter(Boolean).join(' · ')}</span></div>
        <div className="all-settings-preset"><span className="all-settings-preset-label">Filament</span>
          <span className="all-settings-preset-value all-settings-preset-value--list">
            {filaments.map((filament) => <span className="all-settings-preset-slot" key={filament.slot}>
              <Swatch colour={filament.colour} label={filament.material || shortPreset(filament.preset)} />
              Slot {filament.slot} · {shortPreset(filament.preset)}</span>)}
            {filaments.length === 0 && 'None'}</span></div>
        <div className="all-settings-preset"><span className="all-settings-preset-label">Process</span>
          <span className="all-settings-preset-value">{shortPreset(catalog!.process.name)}
            <span className="all-settings-preset-detail">{processChanges > 0
              ? `${plural(processChanges, 'change', 'changes')} from the preset` : 'from the preset'}</span></span></div>
        {activePlate && (activePlate.ownBedType || activePlate.own.length > 0) && <div className="all-settings-preset">
          <span className="all-settings-preset-label">{activePlate.name}</span>
          <span className="all-settings-preset-value">{activePlate.ownBedType ? activePlate.bedType : activePlate.own[0].display}
            <span className="all-settings-preset-detail">{activePlate.ownBedType
              ? `Bed type set on this plate${activePlate.own.length > 1 ? ` · ${plural(activePlate.own.length - 1, 'more plate setting', 'more plate settings')}` : ''}`
              : plural(activePlate.own.length, 'setting set on this plate', 'settings set on this plate')}</span></span></div>}
      </div>
      {withOwn.length > 0 && !saved && <div className="all-settings-own" role="note">
        <p>{withOwn.length === 1
          ? `${withOwn[0].name} has settings of its own${regionsOf(withOwn[0])}.`
          : `${withOwn.map((object) => object.name).join(', ')} have settings of their own.`}</p>
        <p className="all-settings-own-hint">{withOwn.length === 1 ? 'Open it' : 'Open one'} in the 3D view, or choose it above, to see them.</p>
      </div>}
      <div className="all-settings-groups">
        {PROCESS_PAGES.map((page, index) => {
          const rows = byPage.get(page) ?? [];
          const changes = catalog!.process.settings.filter((setting) => pageOf(setting) === page && changed(setting)).length;
          if (rows.length === 0 && (query.trim() || filter === 'changed')) return null;
          return <Group key={page} name={page} summary={summary(changes)} count={rows.length}
            open={isOpen(page, index === 0 || changes > 0)} onToggle={() => toggle(page, index === 0 || changes > 0)}>
            <PresetRows settings={rows} notes={overrideNotes} />
          </Group>;
        })}
        {(filamentCount > 0 || !(query.trim() || filter === 'changed')) && <Group name="Filament" count={filamentCount}
          summary={filaments.length > 1 ? `${plural(filaments.length, 'slot', 'slots')}${filaments.length <= COLUMN_SLOTS ? ', side by side' : ''}`
            : filaments[0] ? [filaments[0].material || shortPreset(filaments[0].preset), filamentChanges > 0 ? `${filamentChanges} changed` : ''].filter(Boolean).join(' · ')
            : 'none'}
          open={isOpen('Filament', filamentChanges > 0)} onToggle={() => toggle('Filament', filamentChanges > 0)}>
          {filaments.length > COLUMN_SLOTS && <div className="all-settings-slot-picker">
            <span className="all-settings-scope-label">Slot</span>
            <ActionMenu label="Slot" appearance="select" text={`Slot ${slot} · ${shortPreset(filaments.find((item) => item.slot === slot)?.preset ?? '')}`}
              items={filaments.map((item) => ({ key: String(item.slot), label: `Slot ${item.slot} · ${item.material || shortPreset(item.preset)}`,
                current: item.slot === slot, onSelect: () => setSlot(item.slot) }))} />
          </div>}
          {filamentShown.length === 1 && <PresetRows settings={filamentRowsShown} byPage />}
          {filamentShown.length > 1 && <FilamentColumns filaments={filamentShown} plate={activePlate} query={query} filter={filter} />}
        </Group>}
        {(printerRows.length > 0 || !(query.trim() || filter === 'changed')) && <Group name="Printer" count={printerRows.length}
          summary={[shortPreset(catalog!.printer.name), printerChanges > 0 ? `${printerChanges} changed` : ''].filter(Boolean).join(' · ')}
          open={isOpen('Printer', printerChanges > 0)} onToggle={() => toggle('Printer', printerChanges > 0)}>
          <PresetRows settings={printerRows} byPage />
        </Group>}
      </div>
    </>;
  };

  // "in 4 regions: 2 mounting tabs and 2 screw holes" -- the volumes an
  // object prints differently, counted by name.
  const regionsOf = (object: CatalogObjectInfo): string => {
    const names = runs(object.overrides.filter((local) => volumeName(local)), (local) => volumeName(local)!)
      .map(([name, locals]) => locals.length > 1 ? `${locals.length} ${name}` : name);
    const regions = object.overrides.filter((local) => volumeName(local)).length;
    return regions === 0 ? '' : ` in ${plural(regions, 'region', 'regions')}: ${names.join(' and ')}`;
  };

  const objectBody = (object: CatalogObjectInfo) => {
    type Entry = { key: string; label: string; value: string; tag: string; note: string; page: string };
    const processRow = (key: string) => catalog!.process.settings.find((setting) => setting.key === key);
    const tagOf = (kind: string) => kind === 'object' ? 'Object' : kind === 'height range' ? 'Height range' : 'Region';
    const entries: Entry[] = [];
    // Two modifiers of one name that set one setting the same way are one
    // row: "Mounting tabs · 2 regions".
    const valued = runs(object.overrides.filter((item) => item.key),
      (item) => [item.kind, item.key, item.value, volumeName(item) ?? ''].join('\u0000'));
    for (const [, locals] of valued) {
      const local = locals[0];
      const row = processRow(local.key);
      const where = volumeName(local) ?? (local.kind === 'object' ? 'Whole object' : sentence(local.kind));
      const regions = locals.length > 1 ? ` · ${plural(locals.length, 'region', 'regions')}` : '';
      // OrcaSlicer stores an object's filament as a slot number, the one
      // setting the panel knows by its key: the slot's preset says more.
      const slotNumber = local.key === 'extruder' ? Number(local.value) : NaN;
      const filament = Number.isInteger(slotNumber) ? catalog!.filaments.find((item) => item.slot === slotNumber) : undefined;
      const projectValue = local.key === 'extruder'
        ? catalog!.filaments[0] ? `1 · ${shortPreset(catalog!.filaments[0].preset)}` : '1' : row?.display ?? 'preset';
      entries.push({ key: `${local.target}:${local.key}`, label: local.label || sentence(local.key),
        value: filament ? `${slotNumber} · ${shortPreset(filament.preset)}` : local.display || local.value, tag: tagOf(local.kind),
        note: `${where}${regions} · project: ${projectValue}`,
        page: local.key === 'extruder' ? 'Filament' : row ? pageOf(row) : 'Others' });
    }
    for (const [kind, locals] of runs(object.overrides.filter((item) => !item.key), (item) => item.kind)) {
      const names = locals.map((local) => volumeName(local) ?? object.name);
      entries.push({ key: kind, label: locals.length > 1 && /blocker|enforcer|part$/.test(kind) ? `${sentence(kind)}s` : sentence(kind),
        value: 'On', tag: /blocker|enforcer|part$/.test(kind) ? 'Region' : 'Object',
        note: `${names.join(', ')}${locals.length > 1 ? ` · ${plural(locals.length, 'region', 'regions')}` : ''}`,
        page: kind.includes('support') ? 'Support' : 'Others' });
    }
    const shown = entries.filter((entry) => matches(entry, query));
    const byPage = new Map(runs(shown, (entry) => entry.page));
    const pages = [...PROCESS_PAGES, 'Filament', 'Printer'];
    return <>
      <div className="all-settings-presets" role="note">
        <p className="all-settings-object-summary">{object.overrides.length === 0
          ? `${object.name} uses the project’s settings and sets nothing of its own.`
          : `${object.name} uses the project’s settings, except${regionsOf(object) || ` for ${plural(object.overrides.length, 'setting', 'settings')} of its own`}.`}</p>
      </div>
      <div className="all-settings-groups">
        {pages.map((page) => {
          const rows = byPage.get(page) ?? [];
          if (rows.length === 0 && query.trim()) return null;
          return <Group key={page} name={page} count={rows.length} summary={rows.length > 0 ? plural(rows.length, 'own setting', 'own settings') : 'same as project'}
            open={isOpen(`object:${page}`, true)} onToggle={() => toggle(`object:${page}`, true)}>
            {rows.map((entry) => <Row key={entry.key} label={entry.label} value={entry.value} tag={entry.tag} notes={[entry.note]} />)}
          </Group>;
        })}
      </div>
    </>;
  };

  const plateBody = (plate: CatalogPlateInfo) => {
    const rows = plate.own.filter((setting) => matches(setting, query));
    const here = objects.filter((object) => object.plateId === plate.id);
    return <>
      <div className="all-settings-presets" role="note">
        <p className="all-settings-object-summary">{plate.own.length === 0
          ? `${plate.name} prints with the project’s settings and sets nothing of its own.`
          : `${plate.name} sets ${plural(plate.own.length, 'setting', 'settings')} of its own; the rest is the project’s.`}</p>
      </div>
      <div className="all-settings-groups">
        <Group name="Plate" count={rows.length} summary={rows.length > 0 ? plural(rows.length, 'own setting', 'own settings') : 'same as project'}
          open={isOpen('plate', true)} onToggle={() => toggle('plate', true)}>
          {rows.map((setting) => <Row key={setting.key} label={setting.label} value={setting.display} bold notes={['Set on this plate']} />)}
        </Group>
        <Group name="Objects" count={here.length} summary={plural(here.length, 'object', 'objects')}
          open={isOpen('p

content.content:
1	// The All settings panel: every setting in force, in the Agent pane's place,
2	// opened from the setup card's "All settings" link (the "JusPrin v2" canvas,
3	// page "Current Setup Card", the four "All settings" boards). The host reads
4	// the table (settings_catalog); this page only arranges it. Showing follows
5	// the selection in the 3D view: the whole project, one plate when the project
6	// has more than one, or one object, for which only what it sets itself is
7	// listed. The first version is read-only: the design's "Use project value"
8	// and "Remove" actions are not offered yet.
9	
10	import { useEffect, useState } from 'react';
11	import { CatalogFilamentInfo, CatalogObjectInfo, CatalogOverrideInfo, CatalogPlateInfo, CatalogSettingInfo,
12	  SettingsCatalogPayload, WorkspaceContext } from '../bridge/protocol';
13	import { ActionMenu, AgentPaneToggle, MenuItem } from './ChatNavigation';
14	
15	export type SettingsScope = { kind: 'project' } | { kind: 'plate'; id: string } | { kind: 'object'; id: string };
16	export type SettingsFilter = 'all' | 'changed';
17	
18	// OrcaSlicer's process tab pages, in its order. A setting the tab does not
19	// index (empty page) is filed under Others.
20	export const PROCESS_PAGES = ['Quality', 'Strength', 'Speed', 'Support', 'Multimaterial', 'Others'];
21	// Side by side up to here; beyond it one slot at a time, from a picker.
22	export const COLUMN_SLOTS = 3;
23	
24	export interface AllSettingsProps {
25	  context: WorkspaceContext;
26	  // Null while the host is reading it. A saved chat has no live table: pass
27	  // catalogFromContext(summary) and `saved`.
28	  catalog: SettingsCatalogPayload | null;
29	  saved?: boolean;
30	  // The host cannot read the table (an older build, or a non-FFF printer
31	  // reports it itself through `available`).
32	  unsupported?: boolean;
33	}
34	
35	function plural(count: number, one: string, many: string): string {
36	  return `${count} ${count === 1 ? one : many}`;
37	}
38	
39	function shortPreset(name: string): string {
40	  const separator = name.indexOf(' @');
41	  return separator < 0 ? name : name.slice(0, separator);
42	}
43	
44	const sentence = (text: string) => {
45	  const words = text.replace(/[_-]+/g, ' ').trim();
46	  return words.charAt(0).toUpperCase() + words.slice(1);
47	};
48	
49	// The volume an override is on ("bracket.stl / Mounting tabs" names the
50	// modifier), or nothing for the object itself.
51	function volumeName(local: CatalogOverrideInfo): string | undefined {
52	  const separator = local.target.indexOf(' / ');
53	  return separator < 0 ? undefined : local.target.slice(separator + 3);
54	}
55	
56	// Which object the 3D view has: exactly one, or none to follow.
57	export function selectedObject(context: WorkspaceContext): string | null {
58	  const selection = context.selection;
59	  return selection.status === 'objects' && selection.objectIds.length === 1 ? selection.objectIds[0] : null;
60	}
61	
62	// A saved chat's table, from the summary the chat saved: the settings that
63	// differed from the presets then, and the objects' own settings. The rest of
64	// the table was not saved, so the panel shows these as the changed ones.
65	export function catalogFromContext(context: WorkspaceContext): SettingsCatalogPayload {
66	  // "0.2 → 0.28 mm" says the unit once; each side gets it back.
67	  const split = (display: string): [string, string] => {
68	    const arrow = display.indexOf(' → ');
69	    if (arrow < 0) return [display, display];
70	    const before = display.slice(0, arrow);
71	    const after = display.slice(arrow + 3);
72	    const unit = after.match(/^-?[\d.,]+ (\D\S*)$/);
73	    return [unit && /^-?[\d.,]+$/.test(before) ? `${before} ${unit[1]}` : before, after];
74	  };
75	  const rows = (type: string): CatalogSettingInfo[] => context.presetDeltas
76	    .filter((delta) => (delta.presetType ?? 'process') === type)
77	    .map((delta) => {
78	      const [presetDisplay, display] = delta.display ? split(delta.display) : [delta.preset, delta.value];
79	      return { key: delta.key, label: delta.label || delta.key, page: delta.page ?? '', group: delta.group ?? '',
80	        value: delta.value, display, preset: delta.preset, presetDisplay };
81	    });
82	  const identity = context.setupIdentity;
83	  const plate = context.plates.find((item) => item.active);
84	  const applied = context.appliedSetup;
85	  return {
86	    available: true,
87	    process: { name: context.printer.process, settings: rows('process') },
88	    printer: { name: identity?.printer ?? context.printer.preset, settings: rows('printer') },
89	    filaments: (identity?.filaments ?? []).map((filament, index) => ({ slot: index + 1, preset: filament.preset,
90	      material: filament.material, colour: '', settings: index === 0 ? rows('filament') : [] })),
91	    plates: plate ? [{ id: plate.id, name: plate.name, active: true, bedType: identity?.plateType ?? '', ownBedType: false,
92	      bedTempKey: '', bedTempInitialKey: '', own: [] }] : [],
93	    objects: (applied?.objects ?? []).map((name, index) => ({
94	      id: plate?.objects.find((item) => item.name === name)?.id ?? `saved-${index}`, name, plateId: plate?.id,
95	      overrides: (applied?.localOverrides ?? []).filter((local) => local.object === index)
96	        .map(({ target, kind, key, value, label, display }) => ({ target, kind, key, value, label, display })) })),
97	  };
98	}
99	
100	const lower = (text: string) => text.toLowerCase();
101	
102	function matches(setting: { label: string; key: string }, query: string): boolean {
103	  const wanted = lower(query.trim());
104	  return !wanted || lower(setting.label).includes(wanted) || lower(setting.key).includes(wanted);
105	}
106	
107	const changed = (setting: CatalogSettingInfo) => setting.preset !== undefined;
108	
109	// Consecutive runs that share a heading, in the order they first appear.
110	function runs<T>(items: T[], heading: (item: T) => string): [string, T[]][] {
111	  const groups = new Map<string, T[]>();
112	  for (const item of items) groups.set(heading(item), [...(groups.get(heading(item)) ?? []), item]);
113	  return [...groups];
114	}
115	
116	const pageOf = (setting: CatalogSettingInfo) => PROCESS_PAGES.includes(setting.page) ? setting.page : 'Others';
117	
118	// -- Rows ---------------------------------------------------------------------
119	
120	function Row({ label, value, bold, muted, notes, tag }: {
121	  label: string; value: string; bold?: boolean; muted?: boolean; notes?: string[]; tag?: string;
122	}) {
123	  return <div className={bold ? 'all-settings-row all-settings-row--changed' : 'all-settings-row'}>
124	    <div className="all-settings-row-line">
125	      <span className="all-settings-row-name" title={label}>{label}</span>
126	      <span className={['all-settings-row-value', bold && 'all-settings-row-value--bold', muted && 'all-settings-row-value--muted']
127	        .filter(Boolean).join(' ')}>{value}</span>
128	      {tag && <span className="all-settings-row-tag">{tag}</span>}
129	    </div>
130	    {(notes ?? []).filter(Boolean).map((note) => <p className="all-settings-row-note" key={note}>{note}</p>)}
131	  </div>;
132	}
133	
134	// A group's header: a disclosure when it has rows, a plain line that says
135	// "same as project" (or whatever `summary` says) when it has none.
136	function Group({ name, summary, open, onToggle, children, count }: {
137	  name: string; summary: string; open: boolean; onToggle: () => void; children?: React.ReactNode; count: number;
138	}) {
139	  if (count === 0)
140	    return <div className="all-settings-group"><div className="all-settings-group-header all-settings-group-header--empty">
141	      <span className="jp-icon jp-icon-chevron-right" aria-hidden="true" />
142	      <span className="all-settings-group-name">{name}</span>
143	      <span className="all-settings-group-summary">{summary}</span>
144	    </div></div>;
145	  return <div className="all-settings-group">
146	    <button type="button" className="all-settings-group-header" aria-expanded={open} onClick={onToggle}>
147	      <span className={`jp-icon jp-icon-chevron-${open ? 'down' : 'right'}`} aria-hidden="true" />
148	      <span className="all-settings-group-name">{name}</span>
149	      <span className="all-settings-group-summary">{summary}</span>
150	    </button>
151	    {open && <div className="all-settings-group-rows">{children}</div>}
152	  </div>;
153	}
154	
155	// Rows of one preset under their Orca groups, as a name and a value; a
156	// changed value is bold with the preset's under it.
157	function PresetRows({ settings, notes, byPage }: {
158	  settings: CatalogSettingInfo[]; notes?: (setting: CatalogSettingInfo) => string[]; byPage?: boolean;
159	}) {
160	  return <>{runs(settings, (setting) => byPage ? [setting.page, setting.group].filter(Boolean).join(' · ') : setting.group)
161	    .map(([heading, rows]) => <div className="all-settings-run" key={heading || '(ungrouped)'}>
162	      {heading && <p className="all-settings-run-name">{heading}</p>}
163	      {rows.map((setting) => <Row key={setting.key} label={setting.label} bold={changed(setting)}
164	        muted={setting.inherited} value={setting.inherited ? 'printer' : setting.display}
165	        notes={[changed(setting) ? `Preset: ${setting.presetDisplay ?? setting.preset}` : '',
166	          setting.inherited ? `From the printer: ${setting.inheritedDisplay}` : '', ...(notes?.(setting) ?? [])]} />)}
167	    </div>)}</>;
168	}
169	
170	// -- The Filament group ---------------------------------------------------------
171	
172	function Swatch({ colour, label }: { colour: string; label: string }) {
173	  return <span className="all-settings-swatch" role="img" aria-label={label} title={label}
174	    style={colour ? { background: colour } : undefined} />;
175	}
176	
177	// The filament rows, with the bed temperature named for the plate type the
178	// shown plate prints with.
179	function filamentRows(filament: CatalogFilamentInfo, plate: CatalogPlateInfo | undefined, query: string,
180	  filter: SettingsFilter): CatalogSettingInfo[] {
181	  return filament.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)))
182	    .map((setting) => plate?.bedType && (setting.key === plate.bedTempKey || setting.key === plate.bedTempInitialKey)
183	      ? { ...setting, label: `${setting.label} · ${plate.bedType}` } : setting);
184	}
185	
186	// Two or three slots side by side: one column per slot, the rows being slot
187	// 1's settings in order. A value inherited from the printer reads "printer";
188	// a filament's own override, or a change from its preset, is bold with a
189	// note under the row.
190	function FilamentColumns({ filaments, plate, query, filter }: {
191	  filaments: CatalogFilamentInfo[]; plate?: CatalogPlateInfo; query: string; filter: SettingsFilter;
192	}) {
193	  const perSlot = filaments.map((filament) => new Map(filament.settings.map((setting) => [setting.key, setting])));
194	  const lead = filamentRows(filaments[0], plate, query, 'all');
195	  // The changed filter keeps a row some slot changed from its preset, or
196	  // sets itself where another slot leaves it to the printer.
197	  const shown = filter === 'all' ? lead : lead.filter((row) => perSlot.some((slot) => {
198	    const cell = slot.get(row.key);
199	    return !!cell && (changed(cell) || overridesPrinter(cell, perSlot, row.key));
200	  }));
201	  return <div className="all-settings-columns" style={{ '--all-settings-slots': filaments.length } as React.CSSProperties}>
202	    <div className="all-settings-columns-head">
203	      <span />
204	      {filaments.map((filament) => <span className="all-settings-column-slot" key={filament.slot}>
205	        <Swatch colour={filament.colour} label={`Slot ${filament.slot} · ${shortPreset(filament.preset)}`} />
206	        <span className="all-settings-column-slot-name">Slot {filament.slot}</span>
207	        <span className="all-settings-column-slot-material">{filament.material || shortPreset(filament.preset)}</span>
208	      </span>)}
209	    </div>
210	    {runs(shown, (setting) => [setting.page, setting.group].filter(Boolean).join(' · ')).map(([heading, group]) =>
211	      <div className="all-settings-run" key={heading || '(ungrouped)'}>
212	        {heading && <p className="all-settings-run-name">{heading}</p>}
213	        {group.map((lead) => {
214	          const cells = perSlot.map((slot) => slot.get(lead.key));
215	          const notes = cells.flatMap((cell, index) => {
216	            if (!cell) return [];
217	            const slot = filaments[index].slot;
218	            const lines: string[] = [];
219	            if (changed(cell)) lines.push(`Slot ${slot} preset: ${cell.presetDisplay ?? cell.preset}`);
220	            if (overridesPrinter(cell, perSlot, lead.key))
221	              lines.push(`Slot ${slot} overrides the printer’s ${printerValue(perSlot, lead.key)}.`);
222	            return lines;
223	          });
224	          const anyBold = cells.some((cell) => cell && (changed(cell) || overridesPrinter(cell, perSlot, lead.key)));
225	          return <div className={anyBold ? 'all-settings-row all-settings-row--changed' : 'all-settings-row'} key={lead.key}>
226	            <div className="all-settings-row-line all-settings-row-line--columns">
227	              <span className="all-settings-row-name" title={lead.label}>{lead.label}</span>
228	              {cells.map((cell, index) => <span key={index} className={['all-settings-row-value',
229	                cell && (changed(cell) || overridesPrinter(cell, perSlot, lead.key)) && 'all-settings-row-value--bold',
230	                cell?.inherited && 'all-settings-row-value--muted'].filter(Boolean).join(' ')}>
231	                {cell ? cell.inherited ? 'printer' : cell.display : '—'}</span>)}
232	            </div>
233	            {notes.map((note) => <p className="all-settings-row-note" key={note}>{note}</p>)}
234	          </div>;
235	        })}
236	      </div>)}
237	  </div>;
238	}
239	
240	// A filament's own value for a setting another slot leaves to the printer.
241	function overridesPrinter(cell: CatalogSettingInfo, perSlot: Map<string, CatalogSettingInfo>[], key: string): boolean {
242	  return !cell.inherited && perSlot.some((slot) => slot.get(key)?.inherited);
243	}
244	
245	function printerValue(perSlot: Map<string, CatalogSettingInfo>[], key: string): string {
246	  for (const slot of perSlot) {
247	    const cell = slot.get(key);
248	    if (cell?.inherited) return cell.inheritedDisplay ?? '';
249	  }
250	  return '';
251	}
252	
253	// -- The panel ------------------------------------------------------------------
254	
255	export function AllSettingsHeader({ onBack, onCollapse }: { onBack: () => void; onCollapse: () => void }) {
256	  return <header className="chat-header all-settings-header">
257	    <button type="button" className="chat-icon" aria-label="Back to chat" title="Back to chat" autoFocus onClick={onBack}>
258	      <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" />
259	    </button>
260	    <h1>All settings</h1>
261	    <AgentPaneToggle onCollapse={onCollapse} />
262	  </header>;
263	}
264	
265	function scopeKey(scope: SettingsScope): string {
266	  return scope.kind === 'project' ? 'project' : `${scope.kind}:${scope.id}`;
267	}
268	
269	export function AllSettings({ context, catalog, saved = false, unsupported = false }: AllSettingsProps) {
270	  const selected = selectedObject(context);
271	  const follow = (id: string | null): SettingsScope | null => id ? { kind: 'object', id } : null;
272	  const [chosen, setChosen] = useState<SettingsScope | null>(() => follow(selected));
273	  // The 3D view's selection wins whenever it changes; a choice made here
274	  // holds until then.
275	  useEffect(() => { setChosen(follow(selected)); }, [selected]);
276	  const [query, setQuery] = useState('');
277	  const [filter, setFilter] = useState<SettingsFilter>(saved ? 'changed' : 'all');
278	  const [slot, setSlot] = useState(1);
279	  const [open, setOpen] = useState<Record<string, boolean>>({});
280	
281	  const plates = catalog?.plates ?? context.plates.map((plate) => ({ id: plate.id, name: plate.name, active: plate.active,
282	    bedType: '', ownBedType: false, bedTempKey: '', bedTempInitialKey: '', own: [] as CatalogSettingInfo[] }));
283	  const objects: CatalogObjectInfo[] = catalog?.objects ?? context.plates.flatMap((plate) =>
284	    plate.objects.map((object) => ({ id: object.id, name: object.name, plateId: plate.id, overrides: [] })));
285	  const scope: SettingsScope = chosen && (chosen.kind === 'project' ||
286	    (chosen.kind === 'object' ? objects : plates).some((item) => item.id === chosen.id)) ? chosen : { kind: 'project' };
287	  const activePlate = plates.find((plate) => plate.active);
288	
289	  const options: MenuItem[] = [
290	    { key: 'project', label: 'Whole project', current: scope.kind === 'project', onSelect: () => setChosen({ kind: 'project' }) },
291	    ...(plates.length > 1 ? plates.map((plate) => ({ key: `plate:${plate.id}`, label: plate.name,
292	      current: scope.kind === 'plate' && scope.id === plate.id, onSelect: () => setChosen({ kind: 'plate', id: plate.id }) })) : []),
293	    ...objects.map((object) => ({ key: `object:${object.id}`, label: object.name,
294	      current: scope.kind === 'object' && scope.id === object.id, onSelect: () => setChosen({ kind: 'object', id: object.id }) })),
295	  ];
296	  const shownName = options.find((option) => option.current)?.label ?? 'Whole project';
297	
298	  const toggle = (name: string, fallback: boolean) => setOpen((before) => ({ ...before, [name]: !(before[name] ?? fallback) }));
299	  const isOpen = (name: string, fallback: boolean) => query.trim() ? true : open[name] ?? fallback;
300	
301	  const identity = context.setupIdentity;
302	  const process = catalog?.process;
303	  const processChanges = process ? process.settings.filter(changed).length
304	    : context.presetDeltas.filter((delta) => (delta.presetType ?? 'process') === 'process').length;
305	  const objectsHere = objects.filter((object) => !activePlate || object.plateId === activePlate.id || !object.plateId);
306	  const withOwn = objectsHere.filter((object) => object.overrides.length > 0);
307	
308	  // What the row of one process setting says about the objects that print
309	  // it differently: "Mounting tabs: 6".
310	  const overrideNotes = (setting: CatalogSettingInfo): string[] => objectsHere.flatMap((object) =>
311	    object.overrides.filter((local) => local.key === setting.key).map((local) =>
312	      `${volumeName(local) ?? object.name}: ${local.display || local.value}`));
313	
314	  const body = () => {
315	    if (unsupported) return <p className="all-settings-note">This JusPrin build cannot list the settings.</p>;
316	    if (!catalog) return <p className="all-settings-note" role="status">Reading the settings…</p>;
317	    if (!catalog.available) return <p className="all-settings-note">No settings to show: the selected printer is not an FFF printer.</p>;
318	    if (scope.kind === 'object') return objectBody(objects.find((object) => object.id === scope.id)!);
319	    if (scope.kind === 'plate') return plateBody(plates.find((plate) => plate.id === scope.id)!);
320	    return projectBody();
321	  };
322	
323	  const projectBody = () => {
324	    const processRows = catalog!.process.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)));
325	    const byPage = new Map(runs(processRows, pageOf));
326	    const printerRows = catalog!.printer.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)));
327	    const filaments = catalog!.filaments;
328	    const filamentShown = filaments.length > COLUMN_SLOTS ? filaments.filter((item) => item.slot === slot) : filaments;
329	    const filamentRowsShown = filamentShown.length === 1 ? filamentRows(filamentShown[0], activePlate, query, filter) : [];
330	    const filamentCount = filamentShown.length === 1 ? filamentRowsShown.length
331	      : filaments.length === 0 ? 0 : filamentRows(filaments[0], activePlate, query, 'all').length;
332	    const filamentChanges = filaments.reduce((total, item) => total + item.settings.filter(changed).length, 0);
333	    const printerChanges = catalog!.printer.settings.filter(changed).length;
334	    const summary = (count: number) => count > 0 ? `${count} changed` : 'from the preset';
335	    return <>
336	      <div className="all-settings-presets" data-testid="all-settings-presets">
337	        <div className="all-settings-preset"><span className="all-settings-preset-label">Printer</span>
338	          <span className="all-settings-preset-value">{[identity?.printer || catalog!.printer.name,
339	            identity?.nozzles.length ? `${identity.nozzles.join(' / ')} mm nozzle` : ''].filter(Boolean).join(' · ')}</span></div>
340	        <div className="all-settings-preset"><span className="all-settings-preset-label">Filament</span>
341	          <span className="all-settings-preset-value all-settings-preset-value--list">
342	            {filaments.map((filament) => <span className="all-settings-preset-slot" key={filament.slot}>
343	              <Swatch colour={filament.colour} label={filament.material || shortPreset(filament.preset)} />
344	              Slot {filament.slot} · {shortPreset(filament.preset)}</span>)}
345	            {filaments.length === 0 && 'None'}</span></div>
346	        <div className="all-settings-preset"><span className="all-settings-preset-label">Process</span>
347	          <span className="all-settings-preset-value">{shortPreset(catalog!.process.name)}
348	            <span className="all-settings-preset-detail">{processChanges > 0
349	              ? `${plural(processChanges, 'change', 'changes')} from the preset` : 'from the preset'}</span></span></div>
350	        {activePlate && (activePlate.ownBedType || activePlate.own.length > 0) && <div className="all-settings-preset">
351	          <span className="all-settings-preset-label">{activePlate.name}</span>
352	          <span className="all-settings-preset-value">{activePlate.ownBedType ? activePlate.bedType : activePlate.own[0].display}
353	            <span className="all-settings-preset-detail">{activePlate.ownBedType
354	              ? `Bed type set on this plate${activePlate.own.length > 1 ? ` · ${plural(activePlate.own.length - 1, 'more plate setting', 'more plate settings')}` : ''}`
355	              : plural(activePlate.own.length, 'setting set on this plate', 'settings set on this plate')}</span></span></div>}
356	      </div>
357	      {withOwn.length > 0 && !saved && <div className="all-settings-own" role="note">
358	        <p>{withOwn.length === 1
359	          ? `${withOwn[0].name} has settings of its own${regionsOf(withOwn[0])}.`
360	          : `${withOwn.map((object) => object.name).join(', ')} have settings of their own.`}</p>
361	        <p className="all-settings-own-hint">{withOwn.length === 1 ? 'Open it' : 'Open one'} in the 3D view, or choose it above, to see them.</p>
362	      </div>}
363	      <div className="all-settings-groups">
364	        {PROCESS_PAGES.map((page, index) => {
365	          const rows = byPage.get(page) ?? [];
366	          const changes = catalog!.process.settings.filter((setting) => pageOf(setting) === page && changed(setting)).length;
367	          if (rows.length === 0 && (query.trim() || filter === 'changed')) return null;
368	          return <Group key={page} name={page} summary={summary(changes)} count={rows.length}
369	            open={isOpen(page, index === 0 || changes > 0)} onToggle={() => toggle(page, index === 0 || changes > 0)}>
370	            <PresetRows settings={rows} notes={overrideNotes} />
371	          </Group>;
372	        })}
373	        {(filamentCount > 0 || !(query.trim() || filter === 'changed')) && <Group name="Filament" count={filamentCount}
374	          summary={filaments.length > 1 ? `${plural(filaments.length, 'slot', 'slots')}${filaments.length <= COLUMN_SLOTS ? ', side by side' : ''}`
375	            : filaments[0] ? [filaments[0].material || shortPreset(filaments[0].preset), filamentChanges > 0 ? `${filamentChanges} changed` : ''].filter(Boolean).join(' · ')
376	            : 'none'}
377	          open={isOpen('Filament', filamentChanges > 0)} onToggle={() => toggle('Filament', filamentChanges > 0)}>
378	          {filaments.length > COLUMN_SLOTS && <div className="all-settings-slot-picker">
379	            <span className="all-settings-scope-label">Slot</span>
380	            <ActionMenu label="Slot" appearance="select" text={`Slot ${slot} · ${shortPreset(filaments.find((item) => item.slot === slot)?.preset ?? '')}`}
381	              items={filaments.map((item) => ({ key: String(item.slot), label: `Slot ${item.slot} · ${item.material || shortPreset(item.preset)}`,
382	                current: item.slot === slot, onSelect: () => setSlot(item.slot) }))} />
383	          </div>}
384	          {filamentShown.length === 1 && <PresetRows settings={filamentRowsShown} byPage />}
385	          {filamentShown.length > 1 && <FilamentColumns filaments={filamentShown} plate={activePlate} query={query} filter={filter} />}
386	        </Group>}
387	        {(printerRows.length > 0 || !(query.trim() || filter === 'changed')) && <Group name="Printer" count={printerRows.length}
388	          summary={[shortPreset(catalog!.printer.name), printerChanges > 0 ? `${printerChanges} changed` : ''].filter(Boolean).join(' · ')}
389	          open={isOpen('Printer', printerChanges > 0)} onToggle={() => toggle('Printer', printerChanges > 0)}>
390	          <PresetRows settings={printerRows} byPage />
391	        </Group>}
392	      </div>
393	    </>;
394	  };
395	
396	  // "in 4 regions: 2 mounting tabs and 2 screw holes" -- the volumes an
397	  // object prints differently, counted by name.
398	  const regionsOf = (object: CatalogObjectInfo): string => {
399	    const names = runs(object.overrides.filter((local) => volumeName(local)), (local) => volumeName(local)!)
400	      .map(([name, locals]) => locals.length > 1 ? `${locals.length} ${name}` : name);
401	    const regions = object.overrides.filter((local) => volumeName(local)).length;
402	    return regions === 0 ? '' : ` in ${plural(regions, 'region', 'regions')}: ${names.join(' and ')}`;
403	  };
404	
405	  const objectBody = (object: CatalogObjectInfo) => {
406	    type Entry = { key: string; label: string; value: string; tag: string; note: string; page: string };
407	    const processRow = (key: string) => catalog!.process.settings.find((setting) => setting.key === key);
408	    const tagOf = (kind: string) => kind === 'object' ? 'Object' : kind === 'height range' ? 'Height range' : 'Region';
409	    const entries: Entry[] = [];
410	    // Two modifiers of one name that set one setting the same way are one
411	    // row: "Mounting tabs · 2 regions".
412	    const valued = runs(object.overrides.filter((item) => item.key),
413	      (item) => [item.kind, item.key, item.value, volumeName(item) ?? ''].join('\u0000'));
414	    for (const [, locals] of valued) {
415	      const local = locals[0];
416	      const row = processRow(local.key);
417	      const where = volumeName(local) ?? (local.kind === 'object' ? 'Whole object' : sentence(local.kind));
418	      const regions = locals.length > 1 ? ` · ${plural(locals.length, 'region', 'regions')}` : '';
419	      // OrcaSlicer stores an object's filament as a slot number, the one
420	      // setting the panel knows by its key: the slot's preset says more.
421	      const slotNumber = local.key === 'extruder' ? Number(local.value) : NaN;
422	      const filament = Number.isInteger(slotNumber) ? catalog!.filaments.find((item) => item.slot === slotNumber) : undefined;
423	      const projectValue = local.key === 'extruder'
424	        ? catalog!.filaments[0] ? `1 · ${shortPreset(catalog!.filaments[0].preset)}` : '1' : row?.display ?? 'preset';
425	      entries.push({ key: `${local.target}:${local.key}`, label: local.label || sentence(local.key),
426	        value: filament ? `${slotNumber} · ${shortPreset(filament.preset)}` : local.display || local.value, tag: tagOf(local.kind),
427	        note: `${where}${regions} · project: ${projectValue}`,
428	        page: local.key === 'extruder' ? 'Filament' : row ? pageOf(row) : 'Others' });
429	    }
430	    for (const [kind, locals] of runs(object.overrides.filter((item) => !item.key), (item) => item.kind)) {
431	      const names = locals.map((local) => volumeName(local) ?? object.name);
432	      entries.push({ key: kind, label: locals.length > 1 && /blocker|enforcer|part$/.test(kind) ? `${sentence(kind)}s` : sentence(kind),
433	        value: 'On', tag: /blocker|enforcer|part$/.test(kind) ? 'Region' : 'Object',
434	        note: `${names.join(', ')}${locals.length > 1 ? ` · ${plural(locals.length, 'region', 'regions')}` : ''}`,
435	        page: kind.includes('support') ? 'Support' : 'Others' });
436	    }
437	    const shown = entries.filter((entry) => matches(entry, query));
438	    const byPage = new Map(runs(shown, (entry) => entry.page));
439	    const pages = [...PROCESS_PAGES, 'Filament', 'Printer'];
440	    return <>
441	      <div className="all-settings-presets" role="note">
442	        <p className="all-settings-object-summary">{object.overrides.length === 0
443	          ? `${object.name} uses the project’s settings and sets nothing of its own.`
444	          : `${object.name} uses the project’s settings, except${regionsOf(object) || ` for ${plural(object.overrides.length, 'setting', 'settings')} of its own`}.`}</p>
445	      </div>
446	      <div className="all-settings-groups">
447	        {pages.map((page) => {
448	          const rows = byPage.get(page) ?? [];
449	          if (rows.length === 0 && query.trim()) return null;
450	          return <Group key={page} name={page} count={rows.length} summary={rows.length > 0 ? plural(rows.length, 'own setting', 'own settings') : 'same as project'}
451	            open={isOpen(`object:${page}`, true)} onToggle={() => toggle(`object:${page}`, true)}>
452	            {rows.map((entry) => <Row key={entry.key} label={entry.label} value={entry.value} tag={entry.tag} notes={[entry.note]} />)}
453	          </Group>;
454	        })}
455	      </div>
456	    </>;
457	  };
458	
459	  const plateBody = (plate: CatalogPlateInfo) => {
460	    const rows = plate.own.filter((setting) => matches(setting, query));
461	    const here = objects.filter((object) => object.plateId === plate.id);
462	    return <>
463	      <div className="all-settings-presets" role="note">
464	        <p className="all-settings-object-summary">{plate.own.length === 0
465	          ? `${plate.name} prints with the project’s settings and sets nothing of its own.`
466	          : `${plate.name} sets ${plural(plate.own.length, 'setting', 'settings')} of its own; the rest is the project’s.`}</p>
467	      </div>
468	      <div className="all-settings-groups">
469	        <Group name="Plate" count={rows.length} summary={rows.length > 0 ? plural(rows.length, 'own setting', 'own settings') : 'same as project'}
470	          open={isOpen('plate', true)} onToggle={() => toggle('plate', true)}>
471	          {rows.map((setting) => <Row key={setting.key} label={setting.label} value={setting.display} bold notes={['Set on this plate']} />)}
472	        </Group>
473	        <Group name="Objects" count={here.length} summary={plural(here.length, 'object', 'objects')}
474	          open={isOpen('plate-objects', true)} onToggle={() => toggle('plate-objects', true)}>
475	          {here.map((object) => <div className="all-settings-row" key={object.id}>
476	            <div className="all-settings-row-line">
477	              <button type="button" className="all-settings-object-link" onClick={() => setChosen({ kind: 'object', id: object.id })}>{object.name}</button>
478	              <span className="all-settings-row-value all-settings-row-value--muted">{object.overrides.length > 0
479	                ? plural(object.overrides.length, 'own setting', 'own settings') : 'same as project'}</span>
480	            </div>
481	          </div>)}
482	        </Group>
483	      </div>
484	    </>;
485	  };
486	
487	  return <main className="all-settings" data-testid="all-settings" data-scope={scopeKey(scope)}>
488	    <div className="all-settings-scope">
489	      <span className="all-settings-scope-label" id="all-settings-showing">Showing</span>
490	      <ActionMenu label="Showing" appearance="select" text={shownName} items={options} />
491	    </div>
492	    <p className="all-settings-hint">{saved ? 'A saved chat’s setup: the settings that differed from the presets when it was saved.'
493	      : scope.kind === 'object' ? `Follows the selection in the 3D view. Shown: only what ${shownName} sets itself.`
494	      : scope.kind === 'plate' ? `Follows the selection in the 3D view. Shown: what ${shownName} sets itself, and its objects.`
495	      : 'Follows the selection in the 3D view.'}</p>
496	    <div className="all-settings-find">
497	      <label className="field-search all-settings-search">
498	        <span className="jp-icon jp-icon-search" aria-hidden="true" />
499	        <input type="search" placeholder="Search settings" aria-label="Search settings" value={query}
500	          onChange={(event) => setQuery(event.target.value)} />
501	      </label>
502	      <div className="jp-segmented all-settings-filter" role="radiogroup" aria-label="Which settings">
503	        {(['all', 'changed'] as const).map((choice) => <button type="button" key={choice} role="radio"
504	          aria-checked={filter === choice} disabled={saved && choice === 'all'}
505	          className={filter === choice ? 'jp-segment selected' : 'jp-segment'} onClick={() => setFilter(choice)}>
506	          {choice === 'all' ? 'All' : 'Changed'}</button>)}
507	      </div>
508	    </div>
509	    {body()}
510	  </main>;
511	}
512

