#pragma once

// JusPrin's synchronous, GUI-thread observer seam for authoritative committed
// project changes. Fork-owned; Orca code reaches it through the neutral
// forwarding header src/slic3r/GUI/ProjectState.hpp.

#include <cstdint>
#include <functional>
#include <map>
#include <memory>
#include <utility>
#include <vector>

namespace Slic3r::GUI {

enum class ProjectStateChangeReason : std::uint32_t {
    None      = 0,
    Selection = 1u << 0,
    Objects   = 1u << 1,
    History   = 1u << 2,
    Transform = 1u << 3,
    Plates    = 1u << 4,
